        if (lift !== 'finger' || i <= 20) fire('pointermove', 2, 130 + quiver(i), 85, g0 + 10 * i + 2);
        if (i === 21 && lift === 'palm') fire('pointerup', 1, 420 - S, 210, g0 + 205, { size: 50 });
        if (i === 21 && lift === 'finger') fire('pointerup', 2, 130, 85, g0 + 205);
        if (!(i % 4)) await wait(1);
