  const { w } = boot({ member: true, before: x => { signedInAs_(MEMBER_)(x); try { x.localStorage.setItem('favs', JSON.stringify(['w:racer', 'w:scramble'])); } catch (e) {} } });
  await wait(300);
  const t = w.__t, d = w.document;
