  const two = Object.assign({}, SUB_SUM, { key: 'q:Q-SUB-2', row: Object.assign({}, SUB_SUM.row, { row_id: 'Q-SUB-2' }) });
  const c2 = subDraw_(w, two);
  ansType_(w, c2.querySelector('.qp-ans-in'), '14');
